fn p36i_camera_caps(
    vm: &mut Engine,
    name: &str,
    sig: &str,
    recv: ObjRef,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    let v = match (name, sig) {
        ("<init>", "(II)V") => {
            put(vm, recv, "mWidth", Value::Int(iarg(args, 0)))?;
            put(vm, recv, "mHeight", Value::Int(iarg(args, 1)))?;
            put(vm, recv, "mZoomSupported", Value::Int(0))?;
            put(vm, recv, "mMaxZoom", Value::Float(1.0))?;
            Value::Null
        }
        ("<init>", "(IIZF)V") => {
            put(vm, recv, "mWidth", Value::Int(iarg(args, 0)))?;
            put(vm, recv, "mHeight", Value::Int(iarg(args, 1)))?;
            put(vm, recv, "mZoomSupported", Value::Int(iarg(args, 2)))?;
            put(
                vm,
                recv,
                "mMaxZoom",
                args.get(3).cloned().unwrap_or(Value::Float(1.0)),
            )?;
            Value::Null
        }
        ("getWidth", "()I") => Value::Int(field_int(vm, recv, "mWidth")),
        ("getHeight", "()I") => Value::Int(field_int(vm, recv, "mHeight")),
        ("isZoomSupported", "()Z") => bool_value(field_bool(vm, recv, "mZoomSupported")),
        ("getMaxZoom", "()F") => Value::Float(field_float(vm, recv, "mMaxZoom")),
        ("describeContents", "()I") => Value::Int(0),
        _ => return Ok(None),
    };
    Ok(Some(v))
}

fn p36i_user_identifier(vm: &mut Engine, user: &Value) -> i32 {
    if let Value::Obj(r) = user {
        if let Ok(Value::Int(id)) = vm.invoke_instance(*r, "getIdentifier", "()I", &[]) {
            return id;
        }
        return field_int(vm, *r, "mHandle");
    }
    0
}

fn p36i_validate_icon_boundary(
    vm: &mut Engine,
    icon: Value,
    calling_user: i32,
) -> Result<Value, VmExit> {
    // StatusHints.validateAccountIconUserBoundary: URI-based icons encoding
    // a different user id are dropped; a non-numeric encoded user surfaces
    // Integer.parseInt's NumberFormatException, as in AOSP.
    if let Value::Obj(r) = icon {
        if let Ok(Value::Int(t)) = vm.invoke_instance(r, "getType", "()I", &[]) {
            // Icon.TYPE_URI = 4, TYPE_URI_ADAPTIVE_BITMAP = 6
            if t == 4 || t == 6 {
                if let Ok(Value::Obj(u)) =
                    vm.invoke_instance(r, "getUri", "()Landroid/net/Uri;", &[])
                {
                    if let Ok(info) =
                        vm.invoke_instance(u, "getEncodedUserInfo", "()Ljava/lang/String;", &[])
                    {
                        if let Some(text) = opt_str(vm, Some(&info)) {
                            let id = text.parse::<i32>().map_err(|_| {
                                throw(
                                    "Ljava/lang/NumberFormatException;",
                                    format!("For input string: \"{text}\""),
                                )
                            })?;
                            if id != calling_user {
                                return Ok(Value::Null);
                            }
                        }
                    }
                }
            }
        }
    }
    Ok(icon)
}

fn p36i_status_hints(
    vm: &mut Engine,
    name: &str,
    sig: &str,
    recv: ObjRef,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    let v = match (name, sig) {
        (
            "<init>",
            "(Ljava/lang/CharSequence;Landroid/graphics/drawable/Icon;Landroid/os/Bundle;)V",
        ) => {
            put(
                vm,
                recv,
                "mLabel",
                args.first().cloned().unwrap_or(Value::Null),
            )?;
            // Binder.getCallingUserHandle() is user 0 in this single-user VM.
            let icon =
                p36i_validate_icon_boundary(vm, args.get(1).cloned().unwrap_or(Value::Null), 0)?;
            put(vm, recv, "mIcon", icon)?;
            put(
                vm,
                recv,
                "mExtras",
                args.get(2).cloned().unwrap_or(Value::Null),
            )?;
            Value::Null
        }
        (
            "<init>",
            "(Landroid/content/ComponentName;Ljava/lang/CharSequence;ILandroid/os/Bundle;)V",
        ) => {
            let res_id = iarg(args, 2);
            let icon = if res_id == 0 {
                Value::Null
            } else {
                let component = oarg(args, 0).ok_or_else(|| npe("packageName"))?;
                let pkg =
                    vm.invoke_instance(component, "getPackageName", "()Ljava/lang/String;", &[])?;
                vm.invoke_static(
                    "Landroid/graphics/drawable/Icon;",
                    "createWithResource",
                    "(Ljava/lang/String;I)Landroid/graphics/drawable/Icon;",
                    &[pkg, Value::Int(res_id)],
                )?
            };
            put(
                vm,
                recv,
                "mLabel",
                args.get(1).cloned().unwrap_or(Value::Null),
            )?;
            let icon = p36i_validate_icon_boundary(vm, icon, 0)?;
            put(vm, recv, "mIcon", icon)?;
            put(
                vm,
                recv,
                "mExtras",
                args.get(3).cloned().unwrap_or(Value::Null),
            )?;
            Value::Null
        }
        ("<init>", "(Landroid/graphics/drawable/Icon;)V") => {
            // @VisibleForTesting constructor: no boundary validation.
            put(
                vm,
                recv,
                "mIcon",
                args.first().cloned().unwrap_or(Value::Null),
            )?;
            Value::Null
        }
        ("setIcon", "(Landroid/graphics/drawable/Icon;)V") => {
            put(
                vm,
                recv,
                "mIcon",
                args.first().cloned().unwrap_or(Value::Null),
            )?;
            Value::Null
        }
        ("getIcon", "(Landroid/content/Context;)Landroid/graphics/drawable/Drawable;") => {
            // Deprecated: mIcon.loadDrawable(context) (NPE when icon is null).
            let icon = get(vm, recv, "mIcon");
            let r = match icon {
                Value::Obj(r) => r,
                _ => return Err(npe("mIcon")),
            };
            vm.invoke_instance(
                r,
                "loadDrawable",
                "(Landroid/content/Context;)Landroid/graphics/drawable/Drawable;",
                args,
            )?
        }
        ("equals", "(Ljava/lang/Object;)Z") => {
            let eq = match oarg(args, 0) {
                Some(o) if class_of(vm, o) == P36I_STATUS_HINTS => {
                    p36i_guest_equals(vm, &get(vm, recv, "mLabel"), &get(vm, o, "mLabel"))
                        && p36i_guest_equals(vm, &get(vm, recv, "mIcon"), &get(vm, o, "mIcon"))
                        && p36i_guest_equals(vm, &get(vm, recv, "mExtras"), &get(vm, o, "mExtras"))
                }
                _ => false,
            };
            bool_value(eq)
        }
        ("hashCode", "()I") => {
            // AOSP: plain sum of the three field hash codes.
            let h = p36i_guest_hash(vm, &get(vm, recv, "mLabel"))
                .wrapping_add(p36i_guest_hash(vm, &get(vm, recv, "mIcon")))
                .wrapping_add(p36i_guest_hash(vm, &get(vm, recv, "mExtras")));
            Value::Int(h)
        }
        ("getPackageName", "()Landroid/content/ComponentName;") => {
            // Deprecated shim: new ComponentName("", "")
            let component = alloc_obj(vm, "Landroid/content/ComponentName;", Vec::new())?;
            let e1 = jstr(vm, "")?;
            let e2 = jstr(vm, "")?;
            let _ = vm.invoke_instance(
                component,
                "<init>",
                "(Ljava/lang/String;Ljava/lang/String;)V",
                &[e1, e2],
            );
            Value::Obj(component)
        }
        ("getLabel", "()Ljava/lang/CharSequence;") => get(vm, recv, "mLabel"),
        ("getIconResId", "()I") => Value::Int(0),
        ("getIcon", "()Landroid/graphics/drawable/Icon;") => get(vm, recv, "mIcon"),
        ("getExtras", "()Landroid/os/Bundle;") => get(vm, recv, "mExtras"),
        ("describeContents", "()I") => Value::Int(0),
        _ => return Ok(None),
    };
    Ok(Some(v))
}

fn p36i_telecom_manager(
    vm: &mut Engine,
    name: &str,
    sig: &str,
    recv: ObjRef,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    // No ITelecomService binder in this VM: AOSP null-service defaults.
    let v = match (name, sig) {
        ("<init>", _) => {
            if let Some(ctx) = args.first() {
                put(vm, recv, "mContext", ctx.clone())?;
            }
            Value::Null
        }
        ("getCallState", "()I") => Value::Int(0), // CALL_STATE_IDLE
        ("isInCall", "()Z") | ("isInManagedCall", "()Z") | ("isRinging", "()Z") => {
            bool_value(false)
        }
        ("isVoiceMailNumber", "(Landroid/telecom/PhoneAccountHandle;Ljava/lang/String;)Z") => {
            bool_value(false)
        }
        ("getDefaultDialerPackage", "()Ljava/lang/String;") => Value::Null,
        ("hasManageOngoingCallsPermission", "()Z") | ("isTtySupported", "()Z") => bool_value(false),
        ("getCurrentTtyMode", "()I") => Value::Int(0), // TTY_MODE_OFF
        ("getAllPhoneAccountsCount", "()I") => Value::Int(0),
        (
            "getPhoneAccount",
            "(Landroid/telecom/PhoneAccountHandle;)Landroid/telecom/PhoneAccount;",
        )
        | ("getVoiceMailNumber", "(Landroid/telecom/PhoneAccountHandle;)Ljava/lang/String;")
        | ("getLine1Number", "(Landroid/telecom/PhoneAccountHandle;)Ljava/lang/String;")
        | ("getUserSelectedOutgoingPhoneAccount", "()Landroid/telecom/PhoneAccountHandle;")
        | ("getConnectionManager", "()Landroid/telecom/PhoneAccountHandle;")
        | ("getSimCallManager", "()Landroid/telecom/PhoneAccountHandle;")
        | ("getPhoneAccountsForPackage", "()Ljava/util/List;") => Value::Null,
        ("getPhoneAccountsSupportingScheme", "(Ljava/lang/String;)Ljava/util/List;")
        | ("getSelfManagedPhoneAccounts", "()Ljava/util/List;")
        | ("getCallCapablePhoneAccounts", "()Ljava/util/List;")
        | ("getCallCapablePhoneAccounts", "(Z)Ljava/util/List;") => p49_list_value(vm, Vec::new())?,
        ("getAllPhoneAccounts", "()Ljava/util/List;")
        | ("getAllPhoneAccountHandles", "()Ljava/util/List;") => vm.invoke_static(
            "Ljava/util/Collections;",
            "emptyList",
            "()Ljava/util/List;",
            &[],
        )?,
        ("getOwnSelfManagedPhoneAccounts", "()Ljava/util/List;") => {
            return Err(throw(
                "Ljava/lang/IllegalStateException;",
                "Telecom is not available".to_string(),
            ));
        }
        ("endCall", "()Z")
        | ("isInEmergencyCall", "()Z")
        | ("handlePinMmi", "(Ljava/lang/String;)Z")
        | ("handlePinMmi", "(Landroid/telecom/PhoneAccountHandle;Ljava/lang/String;)Z") => {
            bool_value(false)
        }
        // Without ITelecomService these AOSP methods simply do nothing.
        ("acceptRingingCall", "()V")
        | ("acceptRingingCall", "(I)V")
        | ("silenceRinger", "()V")
        | ("cancelMissedCallsNotification", "()V") => Value::Null,
        ("getAdnUriForPhoneAccount", "(Landroid/telecom/PhoneAccountHandle;)Landroid/net/Uri;") => {
            // AOSP falls back to the generic ADN content URI.
            let text = jstr(vm, "content://icc/adn")?;
            vm.invoke_static(
                "Landroid/net/Uri;",
                "parse",
                "(Ljava/lang/String;)Landroid/net/Uri;",
                &[text],
            )?
        }
        _ => return Ok(None),
    };
    Ok(Some(v))
}

fn partial36i_telecom_static(
    vm: &mut Engine,
    class: &str,
    name: &str,
    sig: &str,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    let v = match (class, name, sig) {
        (P36I_CALL_AUDIO_STATE, "audioRouteToString", "(I)Ljava/lang/String;") => {
            jstr(vm, p36i_audio_route_to_string(iarg(args, 0)))?
        }
        (
            P36I_STATUS_HINTS,
            "validateAccountIconUserBoundary",
            "(Landroid/graphics/drawable/Icon;Landroid/os/UserHandle;)Landroid/graphics/drawable/Icon;",
        ) => {
            let calling_user =
                p36i_user_identifier(vm, &args.get(1).cloned().unwrap_or(Value::Null));
            p36i_validate_icon_boundary(
                vm,
                args.first().cloned().unwrap_or(Value::Null),
                calling_user,
            )?
        }
        (P36I_VIDEO_PROFILE, "isAudioOnly", "(I)Z") => {
            let s = iarg(args, 0);
            bool_value(s & 0x1 != 0x1 && s & 0x2 != 0x2)
        }
        (P36I_VIDEO_PROFILE, "isTransmissionEnabled", "(I)Z") => {
            bool_value(iarg(args, 0) & 0x1 == 0x1)
        }
        (P36I_VIDEO_PROFILE, "isReceptionEnabled", "(I)Z") => {
            bool_value(iarg(args, 0) & 0x2 == 0x2)
        }
        (P36I_VIDEO_PROFILE, "isBidirectional", "(I)Z") => {
            bool_value(iarg(args, 0) & 0x3 == 0x3)
        }
        (P36I_VIDEO_PROFILE, "isPaused", "(I)Z") => bool_value(iarg(args, 0) & 0x4 == 0x4),
        (P36I_VIDEO_PROFILE, "isVideo", "(I)Z") => {
            let s = iarg(args, 0);
            bool_value(s & 0x1 == 0x1 || s & 0x2 == 0x2 || s & 0x3 == 0x3)
        }
        (P36I_VIDEO_PROFILE, "videoStateToString", "(I)Ljava/lang/String;") => {
            jstr(vm, p36i_video_state_to_string(iarg(args, 0)))?
        }
        (
            P36I_ACCOUNT_HANDLE,
            "areFromSamePackage",
            "(Landroid/telecom/PhoneAccountHandle;Landroid/telecom/PhoneAccountHandle;)Z",
        ) => {
            let pkg_of = |vm: &mut Engine, handle: &Value| -> Result<Option<String>, VmExit> {
                match handle {
                    Value::Obj(h) => {
                        let component = get(vm, *h, "mComponentName");
                        match component {
                            Value::Obj(c) => {
                                let pkg = vm.invoke_instance(
                                    c,
                                    "getPackageName",
                                    "()Ljava/lang/String;",
                                    &[],
                                )?;
                                Ok(opt_str(vm, Some(&pkg)))
                            }
                            _ => Err(npe("getComponentName")),
                        }
                    }
                    _ => Ok(None),
                }
            };
            let a = pkg_of(vm, &args.first().cloned().unwrap_or(Value::Null))?;
            let b = pkg_of(vm, &args.get(1).cloned().unwrap_or(Value::Null))?;
            bool_value(a == b)
        }
        (
            P36I_DOWNLOAD_BUILDER,
            "fromDownloadRequest",
            "(Landroid/telephony/mbms/DownloadRequest;)Landroid/telephony/mbms/DownloadRequest$Builder;",
        ) => {
            let other = oarg(args, 0).ok_or_else(|| npe("other"))?;
            let source = get(vm, other, "sourceUri");
            let dest = get(vm, other, "destinationUri");
            if matches!(source, Value::Null) || matches!(dest, Value::Null) {
                return Err(iae(
                    "Source and destination URIs must be non-null.".to_string()
                ));
            }
            let builder = alloc_obj(vm, P36I_DOWNLOAD_BUILDER, Vec::new())?;
            put(vm, builder, "source", source)?;
            put(vm, builder, "destination", dest)?;
            put(vm, builder, "fileServiceId", get(vm, other, "fileServiceId"))?;
            put(vm, builder, "subscriptionId", get(vm, other, "subscriptionId"))?;
            put(
                vm,
                builder,
                "appIntent",
                get(vm, other, "serializedResultIntentForApp"),
            )?;
            put(vm, builder, "version", Value::Int(1))?;
            Value::Obj(builder)
        }
        _ => return Ok(None),
    };
    Ok(Some(v))
}

fn partial36i_static(
    vm: &mut Engine,
    class: &str,
    name: &str,
    sig: &str,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    if let Some(v) = partial36i_telephony_static(vm, class, name, sig, args)? {
        return Ok(Some(v));
    }
    if let Some(v) = p36i_user_handle_static(vm, class, name, sig, args)? {
        return Ok(Some(v));
    }
    partial36i_telecom_static(vm, class, name, sig, args)
}

fn partial36i_instance(
    vm: &mut Engine,
    recv_class: &str,
    _mref_class: &str,
    name: &str,
    sig: &str,
    recv: ObjRef,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    match recv_class {
        P36I_TELEPHONY_MANAGER => p36i_telephony_manager(vm, name, sig, recv, args),
        P36I_SUBSCRIPTION_MANAGER => p36i_subscription_manager(vm, name, sig, recv, args),
        P36I_SERVICE_STATE => p36i_service_state(vm, name, sig, recv, args),
        P36I_CB_ID_RANGE => p36i_cb_id_range(vm, name, sig, recv, args),
        P36I_FILE_INFO => p36i_file_info(vm, name, sig, recv, args),
        P36I_DOWNLOAD_BUILDER => p36i_download_builder(vm, name, recv, args),
        P36I_DOWNLOAD_REQUEST => p36i_download_request(vm, name, sig, recv, args),
        P36I_TELECOM_MANAGER => p36i_telecom_manager(vm, name, sig, recv, args),
        P36I_ACCOUNT_HANDLE => p36i_account_handle(vm, name, sig, recv, args),
        P36I_ACCOUNT_BUILDER => p36i_account_builder(vm, name, sig, recv, args),
        P36I_PHONE_ACCOUNT => p36i_phone_account(vm, name, sig, recv, args),
        P36I_DISCONNECT_CAUSE => p36i_disconnect_cause(vm, name, sig, recv, args),
        P36I_CALL_AUDIO_STATE => p36i_call_audio_state(vm, name, sig, recv, args),
        P36I_VIDEO_PROFILE => p36i_video_profile(vm, name, sig, recv, args),
        P36I_CAMERA_CAPS => p36i_camera_caps(vm, name, sig, recv, args),
        P36I_STATUS_HINTS => p36i_status_hints(vm, name, sig, recv, args),
        P36I_GATEWAY_INFO => p36i_gateway_info(vm, name, sig, recv, args),
        "Landroid/os/UserHandle;" => p36i_user_handle(vm, name, sig, recv, args),
        _ => Ok(None),
    }
}

// ---- PhoneNumberUtils BCD codec (TS 24.008 called-party BCD) ---------------

fn p36i_bcd_extended(ext_type: i32) -> Option<&'static [u8]> {
    match ext_type {
        1 => Some(b"*#,N;"), // BCD_EXTENDED_TYPE_EF_ADN
        2 => Some(b"*#abc"), // BCD_EXTENDED_TYPE_CALLED_PARTY
        _ => None,
    }
}

fn p36i_bcd_to_char(b: u8, ext_type: i32) -> Option<char> {
    if b < 0xa {
        return Some((b'0' + b) as char);
    }
    let extended = p36i_bcd_extended(ext_type)?;
    extended.get((b - 0xa) as usize).map(|c| *c as char)
}

fn p36i_char_to_bcd(c: char, ext_type: i32) -> Result<u8, VmExit> {
    if c.is_ascii_digit() {
        return Ok(c as u8 - b'0');
    }
    if let Some(extended) = p36i_bcd_extended(ext_type) {
        if let Some(pos) = extended.iter().position(|e| *e as char == c) {
            return Ok(0xa + pos as u8);
        }
    }
    Err(throw(
        "Ljava/lang/RuntimeException;",
        format!("invalid char for BCD {c}"),
    ))
}

fn p36i_bcd_byte(bytes: &[u8], index: i32) -> Result<u8, VmExit> {
    bytes.get(index as usize).copied().ok_or_else(|| {
        throw(
            "Ljava/lang/ArrayIndexOutOfBoundsException;",
            format!("Index {index} out of bounds for length {}", bytes.len()),
        )
    })
}

// internalCalledPartyBCDFragmentToString: returns how far decoding got; an
// invalid nibble stops decoding (AOSP returns from the helper mid-buffer).
fn p36i_bcd_fragment(
    bytes: &[u8],
    offset: i32,
    length: i32,
    ext_type: i32,
) -> Result<String, VmExit> {
    let mut ret = String::new();
    let end = offset.saturating_add(length);
    let mut i = offset;
    while i < end {
        let byte = p36i_bcd_byte(bytes, i)?;
        match p36i_bcd_to_char(byte & 0xf, ext_type) {
            Some(c) => ret.push(c),
            None => return Ok(ret),
        }
        let b = (byte >> 4) & 0xf;
        if b == 0xf && i + 1 == end {
            break;
        }
        match p36i_bcd_to_char(b, ext_type) {
            Some(c) => ret.push(c),
            None => return Ok(ret),
        }
        i += 1;
    }
    Ok(ret)
}

fn p36i_bcd_args(vm: &Engine, args: &[Value]) -> Result<(Vec<u8>, i32, i32), VmExit> {
    let value = args.first().cloned().unwrap_or(Value::Null);
    if matches!(value, Value::Null) {
        return Err(npe("bytes"));
    }
    Ok((p49_byte_values(vm, &value), iarg(args, 1), iarg(args, 2)))
}

fn p36i_bcd_fragment_to_string(
    vm: &mut Engine,
    args: &[Value],
    ext_type: i32,
) -> Result<String, VmExit> {
    // AOSP dereferences bytes only inside the decode loop; a null array
    // surfaces as NPE there too (length <= 0 yields "" without touching it).
    let length = iarg(args, 2);
    if length <= 0 {
        return Ok(String::new());
    }
    let (bytes, offset, _) = p36i_bcd_args(vm, args)?;
    p36i_bcd_fragment(&bytes, offset, length, ext_type)
}

fn p36i_called_party_bcd_to_string(
    vm: &mut Engine,
    args: &[Value],
    ext_type: i32,
) -> Result<String, VmExit> {
    let length = iarg(args, 2);
    if length < 2 {
        return Ok(String::new());
    }
    let (bytes, offset, _) = p36i_bcd_args(vm, args)?;
    // Only the TON field is considered (TOA_International = 0x91).
    let prepend_plus = p36i_bcd_byte(&bytes, offset)? & 0xf0 == 0x91 & 0xf0;
    let ret = p36i_bcd_fragment(&bytes, offset + 1, length - 1, ext_type)?;
    if !prepend_plus {
        return Ok(ret);
    }
    if ret.is_empty() {
        return Ok(String::new());
    }
    Ok(p36i_bcd_insert_plus(&ret))
}

// The MMI-code plus placement AOSP does with two regexes:
// "(^[#*])(.*)([#*])(.*)(#)$" then "(^[#*])(.*)([#*])(.*)" (greedy groups),
// falling back to prepending '+'.
fn p36i_bcd_insert_plus(s: &str) -> String {
    let bytes: Vec<char> = s.chars().collect();
    let is_marker = |c: char| c == '#' || c == '*';
    if bytes.len() >= 2 && is_marker(bytes[0]) {
        // Pattern 1: starts [#*], ends '#'; group3 = last [#*] before the
        // final '#'; group2 empty means that marker is at index 1.
        if bytes.len() >= 3 && bytes[bytes.len() - 1] == '#' {
            let g3 = (1..bytes.len() - 1).rev().find(|&i| is_marker(bytes[i]));
            if let Some(g3) = g3 {
                if g3 == 1 {
                    return format!("{s}+");
                }
                let mut out: String = bytes[..=g3].iter().collect();
                out.push('+');
                out.extend(&bytes[g3 + 1..]);
                return out;
            }
        }
        // Pattern 2: starts [#*]; group3 = last [#*] after index 0.
        if let Some(g3) = (1..bytes.len()).rev().find(|&i| is_marker(bytes[i])) {
            let mut out: String = bytes[..=g3].iter().collect();
            out.push('+');
            out.extend(&bytes[g3 + 1..]);
            return out;
        }
    }
    format!("+{s}")
}

// numberToCalledPartyBCDHelper. Returns Value::Null for an effectively
// empty number (AOSP returns a null byte[]).
fn p36i_number_to_called_party_bcd(
    vm: &mut Engine,
    number: &str,
    include_length: bool,
    ext_type: i32,
) -> Result<Value, VmExit> {
    let chars: Vec<char> = number.chars().collect();
    let has_plus = chars.contains(&'+');
    let effective = chars.len() as i32 - i32::from(has_plus);
    if effective == 0 {
        return Ok(Value::Null);
    }
    let extra_bytes = if include_length { 2 } else { 1 };
    let result_len = ((effective + 1) / 2 + extra_bytes) as usize;
    let mut result = vec![0u8; result_len];
    let mut digit_count: usize = 0;
    for c in &chars {
        if *c == '+' {
            continue;
        }
        let shift = if digit_count & 1 == 1 { 4 } else { 0 };
        result[extra_bytes as usize + (digit_count >> 1)] |=
            (p36i_char_to_bcd(*c, ext_type)? & 0x0f) << shift;
        digit_count += 1;
    }
    if digit_count & 1 == 1 {
        result[extra_bytes as usize + (digit_count >> 1)] |= 0xf0;
    }
    let mut offset = 0;
    if include_length {
        result[offset] = (result_len - 1) as u8;
        offset += 1;
    }
    result[offset] = if has_plus { 0x91 } else { 0x81 };
    p49_new_byte_array(vm, &result)
}

// android.telecom.GatewayInfo: three-field Parcelable value.
fn p36i_gateway_info(
    vm: &mut Engine,
    name: &str,
    sig: &str,
    recv: ObjRef,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    let v = match (name, sig) {
        ("<init>", "(Ljava/lang/String;Landroid/net/Uri;Landroid/net/Uri;)V") => {
            put(
                vm,
                recv,
                "mGatewayProviderPackageName",
                args.first().cloned().unwrap_or(Value::Null),
            )?;
            put(
                vm,
                recv,
                "mGatewayAddress",
                args.get(1).cloned().unwrap_or(Value::Null),
            )?;
            put(
                vm,
                recv,
                "mOriginalAddress",
                args.get(2).cloned().unwrap_or(Value::Null),
            )?;
            Value::Null
        }
        ("getGatewayProviderPackageName", "()Ljava/lang/String;") => {
            get(vm, recv, "mGatewayProviderPackageName")
        }
        ("getGatewayAddress", "()Landroid/net/Uri;") => get(vm, recv, "mGatewayAddress"),
        ("getOriginalAddress", "()Landroid/net/Uri;") => get(vm, recv, "mOriginalAddress"),
        ("isEmpty", "()Z") => {
            // TextUtils.isEmpty(package) || gatewayAddress == null
            let pkg_empty = field_str(vm, recv, "mGatewayProviderPackageName")
                .map(|s| s.is_empty())
                .unwrap_or(true);
            bool_value(pkg_empty || matches!(get(vm, recv, "mGatewayAddress"), Value::Null))
        }
        ("describeContents", "()I") => Value::Int(0),
        _ => return Ok(None),
    };
    Ok(Some(v))
}

// android.os.UserHandle + Process.myUserHandle (supporting surface for
// PhoneAccountHandle; android.os was already partial without a host model
// for these). The VM runs apps as user 0 (Process.myUid() = 10000).
fn p36i_new_user_handle(vm: &mut Engine, user_id: i32) -> Result<Value, VmExit> {
    let r = alloc_obj(vm, "Landroid/os/UserHandle;", Vec::new())?;
    put(vm, r, "mHandle", Value::Int(user_id))?;
    Ok(Value::Obj(r))
}

fn p36i_my_user_id(vm: &mut Engine) -> i32 {
    match vm.invoke_static("Landroid/os/Process;", "myUid", "()I", &[]) {
        Ok(Value::Int(uid)) => uid / 100000,
        _ => 0,
    }
}

fn p36i_user_handle(
    vm: &mut Engine,
    name: &str,
    sig: &str,
    recv: ObjRef,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    let v = match (name, sig) {
        ("<init>", "(I)V") => {
            put(vm, recv, "mHandle", Value::Int(iarg(args, 0)))?;
            Value::Null
        }
        ("getIdentifier", "()I") => Value::Int(field_int(vm, recv, "mHandle")),
        ("isSystem", "()Z") => bool_value(field_int(vm, recv, "mHandle") == 0),
        ("toString", "()Ljava/lang/String;") => jstr(
            vm,
            format!("UserHandle{{{}}}", field_int(vm, recv, "mHandle")),
        )?,
        ("equals", "(Ljava/lang/Object;)Z") => {
            let eq = match oarg(args, 0) {
                Some(o) if class_of(vm, o) == "Landroid/os/UserHandle;" => {
                    field_int(vm, recv, "mHandle") == field_int(vm, o, "mHandle")
                }
                _ => false,
            };
            bool_value(eq)
        }
        ("hashCode", "()I") => Value::Int(field_int(vm, recv, "mHandle")),
        ("describeContents", "()I") => Value::Int(0),
        _ => return Ok(None),
    };
    Ok(Some(v))
}

fn p36i_user_handle_static(
    vm: &mut Engine,
    class: &str,
    name: &str,
    sig: &str,
    args: &[Value],
) -> Result<Option<Value>, VmExit> {
    let v = match (class, name, sig) {
        ("Landroid/os/UserHandle;", "of", "(I)Landroid/os/UserHandle;") => {
            p36i_new_user_handle(vm, iarg(args, 0))?
        }
        // MU_ENABLED profiles: user id is uid / PER_USER_RANGE.
        ("Landroid/os/UserHandle;", "getUserId", "(I)I") => Value::Int(iarg(args, 0) / 100000),
        ("Landroid/os/UserHandle;", "getUserHandleForUid", "(I)Landroid/os/UserHandle;") => {
            p36i_new_user_handle(vm, iarg(args, 0) / 100000)?
        }
        ("Landroid/os/UserHandle;", "myUserId", "()I") => Value::Int(p36i_my_user_id(vm)),
        ("Landroid/os/Process;", "myUserHandle", "()Landroid/os/UserHandle;") => {
            let user_id = p36i_my_user_id(vm);
            p36i_new_user_handle(vm, user_id)?
        }
        _ => return Ok(None),
    };
    Ok(Some(v))
}
